    const item = data.integrations.find((entry)=>entry.id===integrationId) || data.integrations[0];
    const workspace = params.get('workspace') || item.workspace || 'WS-NOVA-PROD';
    const tabUrl = (tab)=>integrationUrl(item.id,tab,workspace);
    const tab = (key,label)=>`<a class="p7-workspace-tab ${activeTab===key?'is-active':''}" href="${tabUrl(key)}">${esc(label)}</a>`;
    const identityHref = `identity-detail.html?identity=${encodeURIComponent(item.authIdentity)}&workspace=${encodeURIComponent(workspace)}`;
    const secretHref = `secrets-credentials.html?workspace=${encodeURIComponent(workspace)}&integration=${encodeURIComponent(item.id)}${item.secretRef?`&secret=${encodeURIComponent(item.secretRef)}`:''}`;
    const relatedDeliveries = data.webhookDeliveries.filter((entry)=>entry.integration===item.id);
    const overview = `<section class="p7-workspace-detail-grid"><article class="p7-panel p7-detail-card">${sectionHead('Integration profile','Contract identity, direction, scope and accountable owner.',status(item.status))}<div class="p7-identity-grid"><div><span>Integration</span><b>${esc(item.id)}</b></div><div><span>Type</span><b>${esc(item.category)}</b></div><div><span>Direction</span><b>${esc(item.directionGlyph)} ${esc(item.direction)}</b></div><div><span>Workspace</span><b>${esc(workspace)}</b></div><div><span>Environment</span><b>${esc(item.environment)}</b></div><div><span>Owner</span><b>${esc(item.owner)}</b></div></div></article><article class="p7-panel p7-detail-card">${sectionHead('Operational posture','Availability and delivery measures have different denominators.')}<div class="p7-identity-grid"><div><span>Availability</span><b>${esc(item.availability)}</b></div><div><span>${esc(item.latencyLabel)}</span><b>${esc(item.p95)}</b></div><div><span>Events / 30D</span><b>${esc(item.events)}</b></div><div><span>Delivery failures</span><b>${esc(item.failures)}</b></div></div>${item.status==='Watch'?`<div class="p7-boundary-note"><b>Watch reason</b><p>${esc(item.watchReason)}</p></div>`:''}</article></section>`;
    const connection = `<section class="p7-workspace-detail-grid"><article class="p7-panel p7-detail-card">${sectionHead('Connection','Endpoint contract and machine-authentication reference.')}<div class="p7-access-list"><div><span>Endpoint type</span><b>${esc(item.endpointType)}</b><small>${esc(item.direction)}</small></div><div><span>Authentication identity</span><b>${esc(item.authIdentity)}</b><small>Machine identity metadata only</small></div><div><span>Signing / secret reference</span><b>${esc(item.secretRef||'Buyer-managed reference')}</b><small>Secret values are never displayed here</small></div></div><div class="p7-detail-actions"><a class="p7-btn is-secondary" href="${identityHref}">Open machine identity</a><a class="p7-btn is-secondary" href="${secretHref}">Open secret reference</a></div></article><article class="p7-panel p7-detail-card">${sectionHead('Connected capability','Related platform capability without duplicating its lifecycle.')}<div class="p7-access-list"><div><span>Workspace</span><b>${esc(workspace)}</b><small>Tenant-scoped operational context</small></div><div><span>Related MCP server</span><b>${esc(item.relatedMcp||'Not MCP-backed')}</b><small>${item.relatedMcp?'Tool/MCP lifecycle remains in Tools & MCP':'No MCP dependency for this contract'}</small></div></div><div class="p7-detail-actions"><a class="p7-btn is-secondary" href="${workspaceUrl(workspace)}">Workspace Detail</a>${item.relatedMcp?`<a class="p7-btn is-secondary" href="tools-mcp.html?mcp=${encodeURIComponent(item.relatedMcp)}">Tools & MCP</a>`:''}</div></article></section>`;
    const events = `<section class="p7-panel p7-detail-card">${sectionHead('Event contracts','Supported inbound/outbound event contracts for this integration.')}<div class="p7-env-config-list">${item.eventContracts.map((eventName,index)=>`<button type="button" data-integration-event="${esc(eventName)}"><div><span class="p7-id">${index+1<10?'0'+(index+1):index+1}</span><b>${esc(eventName)}</b><small>${esc(item.direction)} · schema-governed</small></div>${status('Configured')}</button>`).join('')}</div></section>`;
    const delivery = `<section class="p7-panel p7-detail-card">${sectionHead('Delivery & Retries','Recent attempt evidence, backoff posture and dead-letter state.',`<span class="p7-count">${relatedDeliveries.length} recent</span>`)}${relatedDeliveries.length?`<div class="p7-integration-delivery-list">${relatedDeliveries.map((entry)=>`<button type="button" data-delivery-detail="${esc(entry.id)}"><div><span class="p7-id">${esc(entry.id)}</span><b>${esc(entry.event)}</b><small>${esc(entry.target)} · ${esc(entry.time)}</small></div><code>${esc(entry.http)}</code><span>${esc(entry.duration)}</span>${status(entry.status)}</button>`).join('')}</div>`:`<div class="p7-boundary-note"><b>No recent failed attempt in bundled sample</b><p>Contract metrics remain available on the parent integration page.</p></div>`}</section>`;
    const policies = `<section class="p7-workspace-detail-grid"><article class="p7-panel p7-detail-card">${sectionHead('Delivery policies','Timeout, retry and signing posture.')}<div class="p7-identity-grid"><div><span>Timeout</span><b>${esc(item.timeout)}</b></div><div><span>Retry policy</span><b>${esc(item.retryPolicy)}</b></div><div><span>Signing</span><b>${esc(item.signing)}</b></div><div><span>Data boundary</span><b>${esc(item.dataBoundary)}</b></div></div></article><article class="p7-panel p7-detail-card">${sectionHead('Ownership boundary','Integration contract, identity and secret lifecycles remain distinct.')}<div class="p7-access-list"><div><span>Integration contract</span><b>${esc(item.id)}</b><small>Endpoint, events, retry and delivery</small></div><div><span>Machine identity</span><b>${esc(item.authIdentity)}</b><small>Principal and access scopes</small></div><div><span>Secret lifecycle</span><b>${esc(item.secretRef||'Buyer-managed')}</b><small>Vault reference, rotation and expiry</small></div></div></article></section>`;
