    const content = ({overview,connection,events,delivery,policies,activity})[activeTab] || overview;
    return `${head('Integration Detail', item.name, `${item.id} · ${workspace} · ${item.environment} · ${item.direction}`, `<a class="p7-btn is-secondary" href="integrations.html?workspace=${encodeURIComponent(workspace)}">${icon('arrow-left')}<span>Integrations</span></a><button class="p7-btn is-primary" data-open-test-delivery="${esc(item.id)}">${icon('send')}<span>Test delivery</span></button>`)}<nav class="p7-workspace-tabs" aria-label="Integration detail tabs">${tab('overview','Overview')}${tab('connection','Connection')}${tab('events','Events')}${tab('delivery','Delivery & Retries')}${tab('policies','Policies')}${tab('activity','Activity & Audit')}</nav>${content}`;
