    const enforcement = `<section class="p7-workspace-detail-grid"><article class="p7-panel p7-detail-card">${sectionHead('Enforcement','Where this policy is applied in the Orvexa operational flow.')}<div class="p7-access-list"><div><span>Control point</span><b>${esc(item.enforcement)}</b><small>${esc(item.scope)}</small></div><div><span>Processing context</span><b>${esc(workspace)}</b><small>Production workspace policy context</small></div></div><div class="p7-detail-actions"><a class="p7-btn is-secondary" href="policies-guardrails.html?policy=${encodeURIComponent(item.id)}">Open Guardrails & Policies</a>${item.id==='POL-REGION-06'?`<a class="p7-btn is-secondary" href="environment-detail.html?workspace=${encodeURIComponent(workspace)}&environment=ENV-PROD-001&tab=access">Environment boundary</a>`:''}</div></article><article class="p7-panel p7-detail-card">${sectionHead('Governance boundary','Orvexa records configured enforcement; buyers remain responsible for their legal and regulatory obligations.')}<div class="p7-boundary-note"><b>Template policy workflow</b><p>No compliance certification or legal conclusion is generated by this page.</p></div></article></section>`;
