    const overview = `<section class="p7-workspace-detail-grid"><article class="p7-panel p7-detail-card">${sectionHead('Request overview','Referenced-user request metadata remains separate from the buyer identity system of record.',status(item.status))}<div class="p7-identity-grid"><div><span>Request ID</span><b>${esc(item.id)}</b></div><div><span>Subject reference</span><b>${esc(item.subject)}</b></div><div><span>Region</span><b>${esc(item.region)}</b></div><div><span>Operational due</span><b>${esc(item.due)}</b></div><div><span>Owner</span><b>${esc(item.owner)}</b></div><div><span>Received</span><b>${esc(item.received)}</b></div></div></article><article class="p7-panel p7-detail-card">${sectionHead('Buyer verification reference','Orvexa tracks a buyer-provided verification reference; it does not claim to be the legal identity-verification authority.')}<div class="p7-boundary-note"><b>${esc(item.verificationRef)}</b><p>Buyer-managed verification/evidence reference attached before scoped execution.</p></div></article></section>`;
    const records = `<section class="p7-workspace-detail-grid"><article class="p7-panel p7-detail-card">${sectionHead('Matched Orvexa records','Small bundled evidence summary for the requested scope.')}<div class="p7-access-list"><div><span>Requested scope</span><b>${esc(item.scope)}</b><small>${esc(item.matched)}</small></div><div><span>Processing restriction</span><b>${esc(item.restriction)}</b><small>Configured workflow behavior</small></div><div><span>Related policy</span><b>${esc(item.policy)}</b><small>Policy context remains auditable</small></div></div><div class="p7-detail-actions">${links}</div></article><article class="p7-panel p7-detail-card">${sectionHead('Data boundary','Only Orvexa-linked referenced-user activity is in scope for this template workflow.')}<div class="p7-boundary-note"><b>${esc(item.subject)}</b><p>Names, email addresses and authoritative customer-account identity remain in the buyer system of record.</p></div></article></section>`;
    const workflow = `<section class="p7-panel p7-detail-card">${sectionHead('Privacy workflow','Operational workflow states; deadlines and legal requirements remain buyer-configurable.')}<div class="p7-promotion"><div class="is-done"><span>1</span><b>Received</b><small>${esc(item.received)}</small></div><div class="is-done"><span>2</span><b>Verify scope</b><small>${esc(item.verificationRef)}</small></div><div class="is-done"><span>3</span><b>Locate records</b><small>${esc(item.matched)}</small></div><div class="is-current"><span>4</span><b>Review restrictions</b><small>${esc(item.status)}</small></div><div><span>5</span><b>Execute & record</b><small>Pending governed action</small></div><div><span>6</span><b>Close</b><small>Audit receipt required</small></div></div><div class="p7-detail-actions"><button class="p7-btn is-primary" data-pf-dsr-complete="${esc(item.id)}">Mark demo workflow complete</button><button class="p7-btn is-secondary" data-pf-dsr-extend="${esc(item.id)}">Record extension request</button></div></section>`;
