    const audit = `<section class="p7-panel p7-detail-card">${sectionHead('Activity & Audit','Privacy-request actions are attributable and recorded as operational evidence.')}<div class="p7-activity-records"><div class="is-sky"><span>${esc(item.received)}</span><div><b>${esc(item.request)}</b><small>${esc(item.subject)} · ${esc(item.owner)}</small></div>${status(item.status)}</div><div class="is-mint"><span>Policy</span><div><b>${esc(item.policy)}</b><small>Configured policy link retained</small></div>${status('Configured')}</div></div><div class="p7-detail-actions"><a class="p7-btn is-secondary" href="roles-audit.html?privacyRequest=${encodeURIComponent(item.id)}">Open audit evidence</a></div></section>`;
