  function renderSecrets() {
    const workspace = requestedWorkspace || 'WS-NOVA-PROD';
    const environment = params.get('environment') || 'ENV-PROD-001';
    const org = data.organizations.find((item)=>item.workspace===workspace) || data.organizations[0];
    const dueCount = data.secrets.filter((item)=>item.status==='Rotate').length;
    const rows = data.secrets.map((item) => `<tr class="is-${item.status==='Rotate'?'warn':'good'}" data-search-row data-search="${searchable(Object.values(item).join(' '))}" data-open-secret="${item.id}"><td><div class="p7-secret-ref"><span>${icon('vault')}</span><div><b>${esc(item.displayName)}</b><small>${esc(item.id)}</small></div></div></td><td>${esc(item.class)}</td><td>${esc(item.owner)}</td><td>${esc(item.environment)}</td><td>${esc(item.version)}</td><td>${esc(item.expiry)}</td><td>${status(item.status)}</td><td>${esc(item.dependents)}</td></tr>`).join('');
    const context = `<aside class="pf-workspace-context"><div><span>${icon('vault')}</span><div><small>Credential reference scope</small><b>${esc(org.name)} · ${esc(org.id)} · ${esc(workspace)} · Production</b><p>Identity metadata stays in API Access; this page owns reference, version, expiry, rotation and dependency evidence.</p></div></div><div><a href="${workspaceUrl(workspace,'access')}">Workspace access</a><a href="api-access.html?workspace=${encodeURIComponent(workspace)}&environment=${encodeURIComponent(environment)}">Machine identities</a></div></aside>`;
    return `${head('Credential security', 'Secrets & Credentials', 'Govern managed secret references, versions, expiry, rotation and runtime dependencies without exposing secret material.', button('View all rotations','history') + button('Register reference','shield-plus','primary','data-register-secret'))}
      ${context}
      <section class="p7-vault"><div class="p7-vault-seal">${icon('vault')}<span>SEALED</span></div><div><span class="p7-eyebrow">Secret material is never rendered</span><h2>Orvexa manages references and evidence—not secret values.</h2><p>Only reference metadata, ownership, version, expiry, rotation policy and dependency bindings are available in the UI.</p><div class="p7-vault-stats"><span><b>74</b> managed references</span><span><b>5</b> credential classes</span><span><b>${dueCount}</b> rotation actions due</span><span><b>Never</b> secret material rendered</span></div></div><aside><small>Next rotation</small><strong>9</strong><span>days</span><p>SEC-CRM-04 · Customer Ops</p><button class="p7-btn is-secondary" data-secret-plan-rotation="SEC-CRM-04">${icon('refresh-cw')}<span>Plan rotation</span></button></aside></section>
      <section class="p7-panel p7-table-panel"><div class="p7-toolbar">${sectionHead('Secret registry','5 featured references shown · 74 managed references in the selected governance scope.')}<label class="p7-search">${icon('search')}<input aria-label="Search secrets" data-filter placeholder="Search reference, owner, environment"/></label></div>${tableWrap(['Secret reference','Class','Owner','Environment','Version','Expiry','State','Blast radius'],rows,'p7-secrets-table')}</section>
      ${sectionHead('Blast radius & dependencies','Runtime consumers bound through least-privilege references.', `<span class="p7-count">Dependency bindings audited</span>`)}<section class="p7-binding-grid">${data.secretBindings.map((item) => `<article data-open-secret-binding="${esc(item.secret)}"><header><span class="p7-id">${esc(item.secret)}</span><b>${esc(item.risk)}</b></header><h3>${esc(item.consumers)}</h3><p>${esc(item.policy)}</p><footer>${icon('link-2')} ${esc(item.lastAccess)} · ${esc(item.evidence)}</footer></article>`).join('')}</section>`;
  }

