    const binding = data.secretBindings.find((x)=>x.secret===item.id);
    const rotations = data.secretRotations.filter((x)=>x.secret===item.id);
    const tab = (key,label)=>`<a class="${activeTab===key?'is-active':''}" href="${secretUrl(item.id,key,workspace)}">${esc(label)}</a>`;
